      case 'readback': if (!(failed && parts[parts.length - 1] === 'Save not confirmed ✕')) push(failed ? 'Could not verify ✕' : 'Verified ✓'); break;
      case 'explain': push(failed ? 'Could not read the trace ✕' : 'Read the trace'); break;
