  const open = openTrace(current);
  const req: TurnRequest = kept ?? { text, clientTurnId: crypto.randomUUID(), ...(choiceId ? { choiceId } : {}), ...(confirmationRef ? { confirmationRef } : {}), ...(open ? { openTraceId: open.id } : {}) };
